#include "symrep_bootstrap.hpp"
using namespace symrep;
static void add(Mat&a,const Mat&b,Q scale=Q(1)){require(a.nrow==b.nrow&&a.ncol==b.ncol,"add shape");for(size_t r=0;r<a.nrow;++r){for(auto[c,x]:b[r])a[r].push_back(c,x*scale);normalize(a[r]);}}
int main(int argc,char**argv){try{require(argc==2||argc==4,"usage average_tail_origin OUT [prefix_weight stem]");fs::path out=argv[1];std::string weight=argc==4?argv[2]:"6",stem=argc==4?argv[3]:"affine_tail_w8";auto started=std::chrono::steady_clock::now();auto o=read_matrix(out/(stem+"_TF175_origin.wxf"));size_t masked=0;for(size_t k=1;k<=5;++k){auto a=read_matrix(out/("galois"+std::to_string(k)+"_w"+weight+".wxf")),b=read_matrix(out/("suffix_galois"+std::to_string(k)+"_w2.wxf"));for(size_t i=0;i<o.nrow;++i){Vec v;for(auto[j,x]:o[i])if(a[i][0]*b[j][0]==1)v.push_back(j,x);else++masked;o[i]=std::move(v);}}
 std::cout<<"GALOIS masked="<<masked<<" seconds="<<seconds(started)<<std::endl;
 std::vector<Mat>a,b;for(std::string s:{"cycmat","flipmat"}){a.push_back(transpose(read_matrix(out/"actions"/("prefix_"+s+"_w"+weight+".wxf"))));b.push_back(read_matrix(out/"actions"/("suffix_"+s+"_w2.wxf")));}
 auto move=[&](const Mat&m,size_t g){return mul(mul(a[g],m),b[g]);};Mat avg=o,term=o;for(size_t k=0;k<3;++k){term=move(term,0);add(avg,term);std::cout<<"CYCLIC term="<<k+1<<" avg_nnz="<<avg.nnz()<<" seconds="<<seconds(started)<<std::endl;}term.clear();add(avg,move(avg,1));for(auto&row:avg.rows)for(size_t j=0;j<row.nnz();++j)row[j]/=Q(8);
 require(equal(move(avg,0),avg)&&equal(move(avg,1),avg),"averaged symmetry residual");a.clear();b.clear();auto e=read_matrix(out/"lastpair_E.wxf"),lift=read_matrix(out/"lastpair_rightinverse.wxf"),source=read_matrix(out/(stem+"_pivot_source.wxf"));require(equal(mul(avg,e),mul(source,mul(lift,e))),"averaged tail source changed");write(out/(stem+"_invariant_TF175_origin.wxf"),avg);std::ofstream f(out/(stem+"_invariant.json"));f<<"{\"origin_nonzeros\":"<<avg.nnz()<<",\"galois_terms_removed\":"<<masked<<",\"exact_cyclic_and_reflection_residuals_zero\":true,\"exact_full_affine_tail_residual_zero\":true,\"seconds\":"<<seconds(started)<<",\"scope\":\"D4/Galois averaging of the local affine tail origin only. Global seam and boundaries still required.\"}\n";std::cout<<"COMPLETE invariant_origin_nnz="<<avg.nnz()<<" seconds="<<seconds(started)<<std::endl;
}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}return 0;}
